INSERT INTO "cambio" ("id_cambio", "codigo_cambio", "titulo", "descripcion", "tipo_cambio", "id_impacto", "id_urgencia", "id_prioridad", "id_estado", "justificacion", "plan_implementacion", "plan_rollback", "plan_pruebas", "ventana_inicio", "ventana_fin", "id_ci_afectado", "id_problema_origen", "id_incidente_origen", "id_usuario_solicitante", "id_usuario_responsable", "resultado_pir", "incidentes_inducidos", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion", "estado_registro", "campos_adicionales") VALUES (1, 'RFC-2026-0001', 'Actualizacion de firmware en Firewall perimetral Fortinet v7.4.2', 'Aplicacion de parche de seguridad critico para solucionar vulnerabilidad CVE-2026 y corregir microcortes de VPN.', 'NORMAL', 2, 2, 2, 3, 'Mitigar vulnerabilidades y solucionar el Problema PRB-2026-0001.', '1. Generar backup completo de configuracion. 2. Instalar imagen firmware v7.4.2. 3. Reiniciar nodo pasivo primero y verificar failover.', 'Restaurar imagen anterior v7.2.8 desde el slot de recuperacion secundaria en caso de falla de trafico.', 'Validar tuneles IPsec activos y pruebas de conexion remota con 5 usuarios de prueba.', '2026-10-05T04:00:00.000Z', '2026-10-05T08:00:00.000Z', 3, 1, NULL, 1, 1, NULL, 0, 1, '2026-09-29T00:59:36.828Z', NULL, NULL, true, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "cambio" ("id_cambio", "codigo_cambio", "titulo", "descripcion", "tipo_cambio", "id_impacto", "id_urgencia", "id_prioridad", "id_estado", "justificacion", "plan_implementacion", "plan_rollback", "plan_pruebas", "ventana_inicio", "ventana_fin", "id_ci_afectado", "id_problema_origen", "id_incidente_origen", "id_usuario_solicitante", "id_usuario_responsable", "resultado_pir", "incidentes_inducidos", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion", "estado_registro", "campos_adicionales") VALUES (2, 'RFC-2026-0002', 'Optimizacion de indices e incremento de memoria en PostgreSQL', 'Creacion de indices concurrentes sobre tablas financieras y ajuste de shared_buffers a 16GB.', 'NORMAL', 2, 1, 3, 2, 'Solucion definitiva para el Problema PRB-2026-0002 de lentitud en reportes.', '1. Tomar snapshot de volumen EBS. 2. Ejecutar script CREATE INDEX CONCURRENTLY. 3. Reiniciar servicio postgresql en ventana.', 'DROP INDEX CONCURRENTLY y restaurar postgresql.conf a configuracion previa.', 'Ejecucion de consulta de prueba y verificacion de tiempo de respuesta < 2 segundos.', '2026-10-12T03:00:00.000Z', '2026-10-12T06:00:00.000Z', 2, 2, NULL, 1, 1, NULL, 0, 1, '2026-09-29T00:59:36.828Z', NULL, NULL, true, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "cambio" ("id_cambio", "codigo_cambio", "titulo", "descripcion", "tipo_cambio", "id_impacto", "id_urgencia", "id_prioridad", "id_estado", "justificacion", "plan_implementacion", "plan_rollback", "plan_pruebas", "ventana_inicio", "ventana_fin", "id_ci_afectado", "id_problema_origen", "id_incidente_origen", "id_usuario_solicitante", "id_usuario_responsable", "resultado_pir", "incidentes_inducidos", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion", "estado_registro", "campos_adicionales") VALUES (4, 'RFC-2026-0004', 'Actualización de Arquitectura de Conexiones y Despliegue de PgBouncer en Cluster DB', 'Implementación definitiva de PgBouncer como proxy transaccional de alta concurrencia para resolver permanentemente la causa raíz del Problema PRB.', 'NORMAL', 3, 2, 2, 6, 'Solución de ingeniería definitiva ante el problema de fuga de conexiones identificado en KEDB.', '1. Despliegue de nodo PgBouncer v1.22. 2. Cambio de puerto en cadena de conexión. 3. Monitoreo de 2 horas. 4. Cierre.', 'Revertir tráfico al puerto nativo 5432 y deshabilitar servicio PgBouncer.', 'Inyección de 800 conexiones simultáneas simuladas validando tiempos de respuesta menores a 50ms.', '2026-10-24T03:01:34.261Z', '2026-10-24T05:01:34.261Z', 2, 3, 11, 22, 22, 'Implementación completada con éxito sin incidentes inducidos. PIR satisfactorio.', 0, 22, '2026-10-23T03:01:34.397Z', NULL, NULL, true, '{}'::jsonb) ON CONFLICT DO NOTHING;
