INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (1, 'mod_reinicio_servidor_app', 'Reinicio programado de servidor de aplicaciones', 'Procedimiento operativo estándar de reinicio preventivo o limpieza de memoria en servidores de aplicaciones.', 61, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'bajo', true, NULL, '["El servidor objetivo no aloja servicios transaccionales en caliente durante la ventana elegida.","Se cuenta con respaldo reciente de configuración y punto de restauración.","Se validó previamente que el proceso de inicio de servicios concluye en menos de 15 minutos."]'::jsonb, '{"motivo":"Mantenimiento preventivo rutinario de servidores de aplicaciones para liberar recursos y depurar sockets huérfanos.","plan_pruebas":"Consumo de endpoint /healthz y verificación de logs en /var/log/app/startup.log.","plan_rollback":"En caso de fallo en el arranque, iniciar el nodo secundario en clúster y restaurar snapshot de arranque.","duracion_estimada":"30m","plan_implementacion":"1. Drenar conexiones activas en el balanceador.\n2. Detener servicios de aplicación en orden ordenado.\n3. Ejecutar comando de reinicio del sistema operativo.\n4. Verificar inicio de demonios y health-check HTTP."}'::jsonb, '["plan_implementacion","plan_rollback","impacto","urgencia"]'::jsonb, '[]'::jsonb, 24, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, NULL, '2026-10-03T02:43:03.216Z', NULL, '2026-10-03T02:43:03.216Z') ON CONFLICT DO NOTHING;
INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (2, 'mod_renovacion_certificado_ssl', 'Renovación de certificado digital SSL/TLS', 'Sustitución periódica de certificados de seguridad vencidos o próximos a expirar en servidores web.', 83, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'bajo', true, NULL, '["El nuevo par de llaves y CSR fue firmado por la Autoridad Certificadora (CA) oficial.","La cadena de confianza intermedia está completa y validada offline.","Se probó la instalación en ambiente de staging o preproducción."]'::jsonb, '{"motivo":"Renovación anual programada de certificados TLS para evitar bloqueos por expiración en navegadores de usuario.","plan_rollback":"Restaurar archivos de certificado previo y recargar servicio web.","duracion_estimada":"20m","plan_implementacion":"1. Respaldar certificado actual y llave privada en almacén seguro.\n2. Copiar nuevo certificado (.crt) y bundle intermedio.\n3. Recargar configuración de Nginx / Apache con comando reload (sin corte de servicio).\n4. Verificar handshake TLS con openssl s_client."}'::jsonb, '["plan_implementacion","plan_rollback"]'::jsonb, '[]'::jsonb, 24, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, NULL, '2026-10-03T02:43:03.216Z', NULL, '2026-10-03T02:43:03.216Z') ON CONFLICT DO NOTHING;
INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (3, 'mod_instalacion_software_estacion', 'Instalación o actualización de software autorizado en estación de usuario', 'Despliegue de paquetes de software aprobados del catálogo corporativo en puestos de trabajo.', 62, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'bajo', true, NULL, '["El software está debidamente licenciado y homologado por el área de Ciberseguridad.","El instalador está firmado digitalmente y alojado en el repositorio institucional.","No requiere reinicio obligatorio durante horario laboral de la persona usuaria."]'::jsonb, '{"motivo":"Aprovisionamiento de herramientas ofimáticas u operativas estándar requeridas para el puesto de trabajo.","plan_rollback":"Ejecutar script de desinstalación silenciosa del paquete y restaurar versión anterior si existía.","duracion_estimada":"15m","plan_implementacion":"1. Verificar espacio en disco y compatibilidad de SO.\n2. Ejecutar instalador silencioso mediante agente de gestión.\n3. Validar activación de licencia y permisos de usuario."}'::jsonb, '["plan_implementacion"]'::jsonb, '[]'::jsonb, 12, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, NULL, '2026-10-03T02:43:03.216Z', NULL, '2026-10-03T02:43:03.216Z') ON CONFLICT DO NOTHING;
INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (4, 'mod_parche_seguridad_estacion', 'Aplicación de parche de seguridad validado en estaciones de usuario', 'Distribución masiva de parches acumulativos del sistema operativo previamente testeados en laboratorio.', 84, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'bajo', true, NULL, '["El parche fue probado exitosamente en el grupo piloto durante al menos 7 días sin incidencias.","No se reportaron incompatibilidades con los aplicativos core de la institución.","Se cuenta con política de reinicio diferido para el usuario final."]'::jsonb, '{"motivo":"Mitigación de vulnerabilidades de seguridad conocidas conforme a boletines mensuales del fabricante.","plan_rollback":"Desinstalar la KB específica mediante script remoto y pausar distribución.","duracion_estimada":"45m","plan_implementacion":"1. Habilitar la directiva WSUS / SCCM para el grupo de distribución.\n2. Descargar paquetes en segundo plano.\n3. Programar instalación para el cierre de jornada."}'::jsonb, '["plan_implementacion","plan_rollback"]'::jsonb, '[]'::jsonb, 24, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, NULL, '2026-10-03T02:43:03.216Z', NULL, '2026-10-03T02:43:03.216Z') ON CONFLICT DO NOTHING;
INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (5, 'plt_emergencia_mitigacion_p1', 'Mitigación Urgente por Incidente Mayor P1 (Hotfix / Rollback)', 'Plantilla acelerada para contención inmediata de incidentes de crisis P1 con dictamen de urgencia ECAB.', 82, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'BAJO', true, NULL, '["El procedimiento cuenta con respaldo previo verificado.","Se ejecutará dentro de la ventana de mantenimiento autorizada.","Se cuenta con procedimiento de rollback validado."]'::jsonb, '{"motivo":"Restauración inmediata del servicio crítico ante caída masiva por fallo en regla de firewall/enrutamiento perimetral que impide el acceso a clientes externos (Incidente Mayor P1).","plan_pruebas":"1. Ping y traceroute continuo hacia DNS públicos y gateways de pago.\n2. Validación de handshake TLS desde sondas externas de monitoreo.\n3. Verificación de flujo de sesiones en dashboard del firewall.","plan_rollback":"1. Cargar archivo de respaldo generado en el paso 2 con comando ''restore configuration immediate''.\n2. Reanudar túnel de respaldo alternativo vía enlace BGP secundario.\n3. Notificar inmediatamente al Comité de Emergencia (ECAB).","criterios_exito":"1. Tráfico perimetral restablecido con 0% de pérdidas de paquetes.\n2. Conexiones concurrentes estabilizadas en valores normales (> 4,500 conn/s).\n3. Cierre del estado de Crisis P1 confirmado por NOC y Líder Técnico.","duracion_estimada":"Sin interrupción adicional","plan_implementacion":"1. Conectarse a la consola de gestión perimetral por enlace seguro OOB.\n2. Respaldar política activa actual ''running-config''.\n3. Aplicar regla de contingencia o revertir commit problemático #COMMIT-7712.\n4. Forzar sincronización de clúster activo/pasivo.\n5. Confirmar tráfico saliente y entrante por túneles IPsec."}'::jsonb, '["tipo_cambio"]'::jsonb, '[]'::jsonb, 24, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, 1, '2026-11-15T17:39:21.572Z', NULL, '2026-11-15T17:39:21.572Z') ON CONFLICT DO NOTHING;
INSERT INTO "cambio_modelo_estandar" ("id_modelo", "codigo", "nombre", "descripcion", "categoria_id", "estado", "version_modelo", "propietario_id", "vigencia_desde", "vigencia_hasta", "servicios_aplicables", "clases_ci_aplicables", "entornos_permitidos", "riesgo_fijo", "autorizacion_automatica", "etapa_minima_id", "lista_elegibilidad", "contenido_prellenado", "campos_bloqueados", "ventanas_permitidas", "anticipacion_horas", "limite_frecuencia_ci", "paquete_tareas", "checklist_items", "control_calidad_activo", "umbral_tasa_fallo_pct", "umbral_fallos_consecutivos", "dias_observacion_calidad", "revision_periodica_meses", "fecha_ultima_revision", "veces_usado", "veces_exitoso", "veces_fallido", "incidentes_asociados", "ultimo_uso", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion") VALUES (6, 'plt_normal_actualizacion_servidor', 'Actualización de Software y Parches en Servidores de Producción', 'Plantilla integral para actualización de aplicaciones de negocio, parches de seguridad del SO y dependencias en clusters productivos.', 66, 'APROBADO', 1, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '["produccion","preproduccion","pruebas","desarrollo"]'::jsonb, 'BAJO', true, NULL, '["El procedimiento cuenta con respaldo previo verificado.","Se ejecutará dentro de la ventana de mantenimiento autorizada.","Se cuenta con procedimiento de rollback validado."]'::jsonb, '{"motivo":"Aplicación programada de parches del fabricante y actualización de la versión del motor de aplicación para resolver fallos de estabilidad conocidos y mitigar vulnerabilidades CVE críticas.","plan_pruebas":"1. Verificación de endpoint de salud /healthz con respuesta HTTP 200 en < 50ms.\n2. Simulación de login con usuario de prueba autenticado.\n3. Monitoreo de telemetría de CPU y memoria por 30 minutos.\n4. Validación de transacciones de prueba en pasarela interna.","plan_rollback":"1. Desviar tráfico exclusivamente al nodo funcional no intervenido.\n2. Si el fallo ocurre en ambos, detener servicios con ''systemctl stop app-service''.\n3. Restaurar snapshot de VM previo a la ventana.\n4. Verificar inicio de servicios en versión previa v2.3.8.\n5. Notificar a monitoreo y al Gestor de Cambios.","criterios_exito":"1. 100% de los nodos actualizados y respondiendo en el balanceador.\n2. Cero excepciones 5xx en logs durante la hora posterior a la ventana.\n3. Latencia promedio de transacciones por debajo de 120ms.\n4. Sin alertas activas en Prometheus/Grafana.","duracion_estimada":"15 min (microcorte al conmutar balanceador)","plan_implementacion":"1. Validar respaldo completo de base de datos y snapshot de máquinas virtuales tomado a las 22:45.\n2. Drenar conexiones del Nodo A en el balanceador de carga.\n3. Aplicar paquete de actualización v2.4.1 y verificar logs en /var/log/app.log.\n4. Ejecutar pruebas de humo locales y reincorporar Nodo A al tráfico.\n5. Repetir pasos 2 al 4 para el Nodo B.\n6. Comprobar paridad de versiones y estabilidad en ambos nodos."}'::jsonb, '["tipo_cambio"]'::jsonb, '[]'::jsonb, 24, 5, '[]'::jsonb, '[]'::jsonb, true, '10.0', 2, 90, 6, NULL, 0, 0, 0, 0, NULL, 1, '2026-11-15T17:39:21.807Z', NULL, '2026-11-15T17:39:21.807Z') ON CONFLICT DO NOTHING;
INSERT INTO "campo_personalizado" ("id_campo", "entidad", "codigo", "etiqueta", "descripcion", "tipo", "activo", "propiedades", "formularios_visibles", "pestana_vista", "seccion", "obligatorio", "reglas_condicionales", "orden", "veces_usado", "usuario_creacion", "fecha_creacion") VALUES (1, 'problema', 'cf_comentarios_y_sugerencias', 'Comentarios y sugerencias', 'Ingresa tus comentarios o sugerencias sobre este problema', 'texto_largo', true, '{"unidad":"","opciones":[],"incluir_busqueda":true,"incluir_reportes":true,"prioridad_minima":5,"incluir_auditoria":true}'::jsonb, '["registro","edicion"]'::jsonb, 'detalle', 'F. Adjuntos', 'no', '[]'::jsonb, 1, 0, 1, '2026-10-03T00:09:57.974Z') ON CONFLICT DO NOTHING;
