INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (1, 'problemas', '1.3.4.1', 'campos', 1, true, false, '{"secciones":[{"id":"sec_identificacion","color":"#2563eb","orden":1,"campos":[{"tipo":"texto","ancho":"completo","ayuda":"Mínimo 10 y máximo 150 caracteres. El sistema sugiere problemas abiertos similares.","codigo":"titulo","reglas":[],"visible":true,"etiqueta":"Título del problema","bloqueado":true,"obligatorio":"si","placeholder":"Resumen conciso y claro de la anomalía técnica..."},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Detalle técnico exhaustivo de los síntomas y comportamiento observado.","codigo":"descripcion","reglas":[],"visible":true,"etiqueta":"Descripción / Síntomas observados","bloqueado":true,"obligatorio":"si","placeholder":"Frecuencia de la falla, pasos para reproducirla, hora y duración, mensaje de error y usuarios afectados..."},{"tipo":"lista_origen","ancho":"1/2","ayuda":"Procedencia formal del caso. Dispara reglas condicionales automáticas.","codigo":"origen","reglas":[],"visible":true,"etiqueta":"Origen del problema","bloqueado":true,"obligatorio":"si"},{"tipo":"selector_incidentes","ancho":"1/2","ayuda":"Búsqueda y selección múltiple de incidentes en curso o cerrados.","codigo":"incidentes_vinculados","reglas":[{"campo":"origen","valor":"incidente_recurrente","accion":"hacer_obligatorio","operador":"es_igual_a"}],"visible":true,"etiqueta":"Incidentes relacionados","bloqueado":false,"obligatorio":"condicional"}],"titulo":"A. Identificación"},{"id":"sec_alcance","color":"#0891b2","orden":2,"campos":[{"tipo":"catalogo_servicio","ancho":"1/2","ayuda":"Servicio corporativo del catálogo que experimenta la degradación o falla.","codigo":"servicio_id","reglas":[],"visible":true,"etiqueta":"Servicio Afectado","bloqueado":true,"obligatorio":"si"},{"tipo":"categoria_cascada","ancho":"1/2","ayuda":"Clasificación taxonómica de 2 niveles.","codigo":"categoria_id","reglas":[],"visible":true,"etiqueta":"Categoría y Subcategoría","bloqueado":false,"obligatorio":"si"},{"tipo":"selector_ci_cmdb","ancho":"completo","ayuda":"Todos los CI involucrados en la falla registrados en la CMDB.","codigo":"ci_afectados","reglas":[],"visible":true,"etiqueta":"Elementos de Configuración (CI) / Activos","bloqueado":false,"obligatorio":"no"}],"titulo":"B. Alcance del Problema"},{"id":"sec_clasificacion","color":"#d97706","orden":3,"campos":[{"tipo":"lista_impacto","ancho":"1/3","ayuda":"Alta, Media o Baja conforme a los acuerdos institucionales.","codigo":"impacto","reglas":[],"visible":true,"etiqueta":"Impacto en el Negocio","bloqueado":true,"obligatorio":"si"},{"tipo":"lista_urgencia","ancho":"1/3","ayuda":"Velocidad requerida para la contención o workaround.","codigo":"urgencia","reglas":[],"visible":true,"etiqueta":"Urgencia Operativa","bloqueado":true,"obligatorio":"si"},{"tipo":"prioridad_calculada","ancho":"1/3","ayuda":"Calculada automáticamente por la matriz ITIL 4.","codigo":"prioridad","reglas":[],"visible":true,"etiqueta":"Prioridad Resultante","bloqueado":true,"obligatorio":"si","solo_lectura":true}],"titulo":"C. Clasificación y Priorización"},{"id":"sec_asignacion","color":"#4f46e5","orden":4,"campos":[{"tipo":"lista_grupo","ancho":"1/2","ayuda":"Unidad técnica responsable de la investigación.","codigo":"grupo_id","reglas":[],"visible":true,"etiqueta":"Grupo Resolutor de TI","bloqueado":false,"obligatorio":"si"},{"tipo":"lista_tecnico","ancho":"1/2","ayuda":"Técnico asignado; si queda vacío se deposita en la bandeja del grupo.","codigo":"responsable_id","reglas":[],"visible":true,"etiqueta":"Especialista Responsable","bloqueado":false,"obligatorio":"no"}],"titulo":"D. Asignación Resolutora"},{"id":"sec_mitigacion","color":"#059669","orden":5,"campos":[{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Permite restablecer temporalmente la continuidad operativa.","codigo":"workaround","reglas":[],"visible":true,"etiqueta":"Solución Temporal / Workaround Conocido","bloqueado":false,"obligatorio":"no","placeholder":"Procedimiento paso a paso para eludir la falla mientras se determina la causa raíz..."}],"titulo":"E. Mitigación y Workaround"},{"id":"sec_adjuntos","color":"#64748b","orden":6,"campos":[{"tipo":"archivo_multiple","ancho":"completo","ayuda":"Límite: 25 MB por archivo. Prohibidos ejecutables por política ISO 27001.","codigo":"adjuntos","reglas":[],"visible":true,"etiqueta":"Evidencias Técnicas (Logs, Capturas, Trazas)","bloqueado":false,"obligatorio":"no"}],"titulo":"F. Evidencias y Adjuntos"}],"campos_bloqueados":["titulo","descripcion","servicio_id","impacto","urgencia"],"formulario_activo":"registro"}'::jsonb, NULL, 'Inicialización de fábrica de la configuración de campos para Gestión de Problemas ITIL 4', NULL, NULL, '2026-10-02T22:13:32.315Z') ON CONFLICT DO NOTHING;
