INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (12, 'gestion_de_cambios', '1.3.3.2', 'reglas_clasificacion', 1, true, false, '{"reglas":[{"id":"regla_clasif_1","orden":1,"accion":"reclasificar_tipo","activa":true,"cuando":"al_cambiar_riesgo","nombre":"Estándar con riesgo mayor a Bajo reclasifica a Normal","mensaje":"Los cambios estándar no pueden tener un riesgo mayor a Bajo según directriz ITIL 4. Se ha reclasificado automáticamente a cambio Normal.","condiciones":{"tipo_cambio":"estandar","riesgo_mayor_que":"bajo"},"tipo_destino":"normal","veces_aplicada":0},{"id":"regla_clasif_2","orden":2,"accion":"reclasificar_tipo","activa":true,"cuando":"al_agregar_ci","nombre":"Estándar sobre CI de criticidad Alta o Crítica reclasifica a Normal","mensaje":"Los activos y CIs de criticidad Alta o Crítica exigen análisis técnico formal y no califican para procedimiento estándar.","condiciones":{"tipo_cambio":"estandar","criticidad_ci_en":["alta","critica"]},"tipo_destino":"normal","veces_aplicada":0},{"id":"regla_clasif_3","orden":3,"accion":"bloquear_con_mensaje","activa":true,"cuando":"al_cambiar_fechas","nombre":"Normal con inicio antes de la anticipación mínima","mensaje":"La fecha de inicio no cumple la anticipación mínima requerida (72 horas). Solicita el cambio como Emergencia o reprograma la fecha.","condiciones":{"tipo_cambio":"normal","fuera_anticipacion_minima":true},"veces_aplicada":0},{"id":"regla_clasif_4","orden":4,"accion":"agregar_etapa_aprobacion","activa":true,"cuando":"al_enviar","nombre":"Normal sobre CI productivo de criticidad alta fuera de ventana","mensaje":"Intervención fuera de ventana en activo productivo crítico: se incorpora obligatoriamente la etapa de Aprobación de Excepción de Ventana.","condiciones":{"entorno":"produccion","tipo_cambio":"normal","criticidad_ci_en":["alta","critica"],"fuera_de_ventana":true},"veces_aplicada":0,"etapa_a_agregar":"excepcion_ventana"},{"id":"regla_clasif_5","orden":5,"accion":"agregar_etapa_aprobacion","activa":true,"cuando":"al_enviar","nombre":"Cualquier tipo dentro de período de congelamiento","mensaje":"La ventana coincide con un período de congelamiento institucional activo. Se requiere autorización de Excepción de Congelamiento.","condiciones":{"dentro_congelamiento":true},"veces_aplicada":0,"etapa_a_agregar":"excepcion_congelamiento"},{"id":"regla_clasif_6","orden":6,"accion":"etiquetar_y_notificar","activa":true,"cuando":"al_enviar","nombre":"Etiquetado y alerta inmediata de Emergencia","mensaje":"Cambio clasificado como Emergencia. Se convoca automáticamente al Comité de Emergencia (ECAB).","etiqueta":"Emergencia","condiciones":{"tipo_cambio":"emergencia"},"veces_aplicada":0,"notificar_roles":["gestor_cambios","supervisor"]}],"estrategia_evaluacion":"todas","riesgo_maximo_modelo_estandar":"bajo"}'::jsonb, '{}'::jsonb, 'Versión de fábrica inicial ITIL v4', 'Instalación de fábrica 1.3.3.2', 1, '2026-10-03T02:43:03.216Z') ON CONFLICT DO NOTHING;
INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (13, 'gestion_de_cambios', '1.3.3.3', 'estados', 1, true, false, '{"estados":[{"id":"solicitado","tipo":"inicial","color":"#6366f1","orden":1,"reloj":"evaluacion","activo":true,"codigo":"solicitado","nombre":"Solicitado","es_sistema":true,"descripcion":"RFC registrada en el sistema a la espera de evaluación inicial o autoautorización por modelo.","permite_editar":"si","tipos_aplicables":["estandar","normal","emergencia"],"aparece_calendario":false,"cuenta_como_abierto":true,"reloj_comportamiento":"corre"},{"id":"en_evaluacion","tipo":"en_evaluacion","color":"#3b82f6","orden":2,"reloj":"evaluacion","activo":true,"codigo":"en_evaluacion","nombre":"En evaluación","es_sistema":false,"descripcion":"Análisis técnico, de riesgos, dependencias y conflictos por parte del evaluador asignado.","permite_editar":"si","tipos_aplicables":["normal"],"aparece_calendario":false,"cuenta_como_abierto":true,"reloj_comportamiento":"corre"},{"id":"en_pausa","tipo":"en_pausa","color":"#f59e0b","orden":3,"reloj":"ninguno","activo":true,"codigo":"en_pausa","nombre":"En pausa","es_sistema":false,"descripcion":"Flujo detenido a la espera de aclaraciones o información complementaria solicitada al solicitante.","permite_editar":"solo_comentarios","tipos_aplicables":["estandar","normal","emergencia"],"aparece_calendario":false,"cuenta_como_abierto":true,"reloj_comportamiento":"pausa"},{"id":"en_autorizacion","tipo":"en_autorizacion","color":"#8b5cf6","orden":4,"reloj":"autorizacion","activo":true,"codigo":"en_autorizacion","nombre":"En autorización","es_sistema":false,"descripcion":"Sometido al circuito de aprobación de acuerdo a la matriz de autoridad y niveles de riesgo.","permite_editar":"solo_comentarios_y_tareas","tipos_aplicables":["estandar","normal","eme