INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (17, 'gestion_de_cambios', '1.3.3.3', 'plazos_escalamiento', 1, true, false, '{"reglas_escalamiento":[{"id":"esc_1","accion":"notificar","activa":true,"nombre":"Recordatorio preventivo al aprobador","mensaje":"La aprobación de la RFC ha alcanzado el 75% del plazo establecido. Por favor revise el caso a la brevedad.","objetivo":"autorizacion","prioridades":["p1","p2","p3","p4"],"umbral_tipo":"porcentaje_plazo","umbral_valor":75,"destinatarios":["aprobador_pendiente"],"max_repeticiones":1,"repetir_cada_horas":0},{"id":"esc_2","accion":"notificar_y_suplente","activa":true,"nombre":"Alerta crítica de inminencia de vencimiento","mensaje":"La aprobación de la RFC está al 90% del tiempo límite. Se alerta al suplente formal y al Gestor de Cambios.","objetivo":"autorizacion","prioridades":["p1","p2","p3","p4"],"umbral_tipo":"porcentaje_plazo","umbral_valor":90,"destinatarios":["suplente_aprobador","gestor_cambios"],"max_repeticiones":1,"repetir_cada_horas":0},{"id":"esc_3","accion":"etiquetar_y_escalar_superior","activa":true,"nombre":"Escalamiento por vencimiento formal","mensaje":"El plazo de autorización ha vencido formalmente. Se escala al superior jerárquico. Nunca se aprueba de forma automática.","etiqueta":"Vencido","objetivo":"autorizacion","prioridades":["p1","p2","p3","p4"],"umbral_tipo":"vencido_horas","umbral_valor":0,"destinatarios":["superior_jerarquico","gestor_cambios"],"max_repeticiones":3,"repetir_cada_horas":12},{"id":"esc_4","accion":"notificar_direccion","activa":true,"nombre":"Escalamiento de Emergencia sin respuesta ECAB","mensaje":"Emergencia sin decisión del ECAB tras 30 minutos de su convocatoria. Se notifica de urgencia a Dirección Institucional.","etiqueta":"Emergencia en Riesgo","objetivo":"autorizacion","prioridades":["p1"],"umbral_tipo":"vencido_horas","umbral_valor":0.5,"destinatarios":["direccion"],"max_repeticiones":2,"repetir_cada_horas":1}],"plazos_por_prioridad":[{"prioridad_id":"p1","evaluacion_horas":2,"prioridad_nombre":"P1 - Crítica","plazo_por_etapa_horas":1,"primera_respuesta_horas":0.5,"autorizacion_total_horas":2},{"prioridad_id":"p2","evaluacion_horas":12,"prioridad_nombre":"P2 - Alta","plazo_por_etapa_horas":8,"primera_respuesta_horas":2,"autorizacion_total_horas":24},{"prioridad_id":"p3","evaluacion_horas":48,"prioridad_nombre":"P3 - Media","plazo_por_etapa_horas":24,"primera_respuesta_horas":8,"autorizacion_total_horas":72},{"prioridad_id":"p4","evaluacion_horas":72,"prioridad_nombre":"P4 - Baja","plazo_por_etapa_horas":48,"primera_respuesta_horas":24,"autorizacion_total_horas":120}],"parametros_adicionales":{"tipo_computo_tiempo":"horas_habiles","tolerancia_inicio_minutos":30,"vigencia_autorizacion_dias":{"normal":7,"estandar":30,"emergencia":1},"horas_diferencia_reprogramacion_reautorizar":24}}'::jsonb, '{"cambios":["Configuración inicial de fábrica v1"]}'::jsonb, 'Versión inicial de fábrica ITIL 4 / COBIT BAI06', NULL, 1, '2026-10-03T02:57:08.388Z') ON CONFLICT DO NOTHING;
