onsable_rol":"gestor_cambios","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false},{"id":"gng_2","orden":2,"texto":"Respaldo verificado e íntegro con prueba de restauración","obligatorio":true,"responsable_rol":"implementador","tipos_aplicables":["normal","emergencia"],"evidencia_requerida":true},{"id":"gng_3","orden":3,"texto":"Plan de rollback revisado y recursos de reversión disponibles","obligatorio":true,"responsable_rol":"implementador","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false},{"id":"gng_4","orden":4,"texto":"Ventana confirmada en calendario sin conflictos bloqueantes","obligatorio":true,"responsable_rol":"gestor_cambios","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false},{"id":"gng_5","orden":5,"texto":"Implementador y equipo de soporte asignados y disponibles","obligatorio":true,"responsable_rol":"supervisor","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false},{"id":"gng_6","orden":6,"texto":"Usuarios de áreas afectadas debidamente notificados de la interrupción","obligatorio":true,"responsable_rol":"gestor_cambios","tipos_aplicables":["normal"],"evidencia_requerida":false},{"id":"gng_7","orden":7,"texto":"Pruebas previas en ambiente de pruebas o preproducción validadas","obligatorio":true,"responsable_rol":"implementador","tipos_aplicables":["normal"],"evidencia_requerida":true},{"id":"gng_8","orden":8,"texto":"Contactos de escalamiento técnico y proveedores en guardia","obligatorio":true,"responsable_rol":"supervisor","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false},{"id":"gng_9","orden":9,"texto":"Accesos, contraseñas temporales y credenciales de ejecución disponibles","obligatorio":true,"responsable_rol":"implementador","tipos_aplicables":["estandar","normal","emergencia"],"evidencia_requerida":false}],"conversion_plan_a_tareas":{"fase_por_defecto":"implementacion","convertir_pasos_en_tar