INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (19, 'gestion_de_cambios', '1.3.3.3', 'implementacion_cierre', 1, true, false, '{"cierre":{"permitir_reapertura":false,"exigir_codigo_cierre":true,"exigir_resumen_cierre":true,"exigir_motivo_reapertura":true,"cierre_automatico_dias_sin_pir":5,"excepcion_reapertura_gestor_dias":3},"actualizacion_cmdb":{"notificar_gestor_activos":true,"aplicar_automaticamente_en_exitoso":false,"exigir_plan_actualizacion_cmdb_antes_programar":true,"bloquear_cierre_si_hay_actualizaciones_cmdb_pendientes":true},"resultado_bitacora":{"campos_exigidos":["resultado","fecha_inicio_real","fecha_fin_real","duracion_interrupcion_real","bitacora_detallada"],"bitacora_obligatoria":true,"tolerancia_fin_minutos":30,"tolerancia_inicio_minutos":30,"exigir_motivo_exceso_ventana":true},"acciones_por_resultado":{"exitoso":{"programar_pir_segun_tipo":true},"parcial":{"forzar_pir":true,"exigir_descripcion_pendiente":true,"crear_rfc_seguimiento_opcional":true},"fallido_o_rollback":{"etiquetar_ci":true,"etiquetar_rfc":["Fallido","Rollback"],"notificar_roles":["gestor_cambios","supervisor","responsables_servicio"],"heredar_prioridad":true,"exigir_causa_fallo":true,"plantilla_problema":"Investigación de causa raíz por fallo de RFC","plantilla_incidente":"Incidente mayor por cambio fallido","forzar_pir_obligatoria":true,"crear_incidente_vinculado":true,"crear_problema_si_sugiere":true,"suspender_modelo_estandar_si_aplica":true}}}'::jsonb, '{"cambios":["Configuración inicial de fábrica v1"]}'::jsonb, 'Versión inicial de fábrica ITIL 4 / COBIT BAI06', NULL, 1, '2026-10-03T02:57:08.868Z') ON CONFLICT DO NOTHING;
INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (20, 'gestion_de_cambios', '1.3.3.3', 'pir', 1, true, false, '{"preguntas":[{"id":"pir_q1","orden":1,"texto":"¿Se lograron los objetivos propuestos del cambio?","opciones":["Totalmente","Parcialmente","No se lograron"],"obligatoria":true,"tipo_respuesta":"lista","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q2","orden":2,"texto":"Evaluación y resultado de cada criterio de éxito verificable","opciones":[],"obligatoria":true,"tipo_respuesta":"texto","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q3","orden":3,"texto":"¿La implementación se completó dentro de la ventana de mantenimiento autorizada?","opciones":["Sí","No"],"obligatoria":true,"tipo_respuesta":"booleano","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q4","orden":4,"texto":"Desviaciones o imprevistos detectados respecto al plan técnico original","opciones":[],"obligatoria":false,"tipo_respuesta":"texto","tipos_aplicables":["normal","emergencia"]},{"id":"pir_q5","orden":5,"texto":"Incidentes causados o atribuibles al cambio durante y tras la ventana","opciones":[],"obligatoria":true,"tipo_respuesta":"texto","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q6","orden":6,"texto":"¿Se ejecutó el plan de rollback? Indicar motivo, tiempo empleado y efectividad","opciones":[],"obligatoria":true,"tipo_respuesta":"texto","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q7","orden":7,"texto":"¿El nivel de riesgo calculado en la evaluación previa fue adecuado?","opciones":["Menor que el riesgo real","Adecuado","Mayor que el riesgo real"],"obligatoria":true,"tipo_respuesta":"lista","tipos_aplicables":["normal","emergencia"]},{"id":"pir_q8","orden":8,"texto":"¿Fue oportuna y clara la comunicación a los usuarios y áreas afectadas?","opciones":["Excelente","Adecuada","Deficiente","No requirió"],"obligatoria":true,"tipo_respuesta":"lista","tipos_aplicables":["normal","emergencia"]},{"id":"pir_q9","orden":9,"texto":"Consumo de recursos, costos y horas hombre (real vs. estimado)","opciones":[],"obligatoria":false,"tipo_respuesta":"texto","tipos_aplicables":["normal"]},{"id":"pir_q10","orden":10,"texto":"¿Se actualizaron todos los atributos y relaciones en la CMDB?","opciones":["Sí","No"],"obligatoria":true,"tipo_respuesta":"booleano","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q11","orden":11,"texto":"¿Se generaron o actualizaron artículos en la Base de Conocimiento (KEDB)?","opciones":["Sí","No"],"obligatoria":true,"tipo_respuesta":"booleano","tipos_aplicables":["estandar","normal","emergencia"]},{"id":"pir_q12","orden":12,"texto":"Lecciones aprendidas principales y oportunidades de mejora identificadas","opciones":[],"obligatoria":true,"tipo_respuesta":"texto","tipos_aplicables":["estandar","normal","emergencia"]}],"parametros":{"revisor_permitido":"gestor_cambios_o_supervisor","plazo_completar_dias":5,"habilitar_acciones_mejora":true,"calificaciones_disponibles":["exitoso","con_observaciones","fallido"],"prohibir_implementador_revisor":true,"bloquear_cierre_hasta_completar":true,"ventana_observacion_incidentes_horas":72},"obligatoriedad_consolidada":[{"riesgo":"cualquiera","resultado":"exitoso","obligatoria":true,"tipo_cambio":"normal","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"parcial","obligatoria":true,"tipo_cambio":"normal","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"fallido","obligatoria":true,"tipo_cambio":"normal","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"rollback","obligatoria":true,"tipo_cambio":"normal","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"exitoso","obligatoria":true,"tipo_cambio":"emergencia","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"parcial","obligatoria":true,"tipo_cambio":"emergencia","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"fallido","obligatoria":true,"tipo_cambio":"emergencia","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"rollback","obligatoria":true,"tipo_cambio":"emergencia","muestreo_pct":100},{"riesgo":"bajo","resultado":"exitoso","obligatoria":false,"tipo_cambio":"estandar","muestreo_pct":10},{"riesgo":"cualquiera","resultado":"parcial","obligatoria":true,"tipo_cambio":"estandar","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"fallido","obligatoria":true,"tipo_cambio":"estandar","muestreo_pct":100},{"riesgo":"cualquiera","resultado":"rollback","obligatoria":true,"tipo_cambio":"estandar","muestreo_pct":100}]}'::jsonb, '{"cambios":["Configuración inicial de fábrica v1"]}'::jsonb, 'Versión inicial de fábrica ITIL 4 / COBIT BAI06', NULL, 1, '2026-10-03T02:57:09.111Z') ON CONFLICT DO NOTHING;
