INSERT INTO "configuracion_modulo_versiones" ("id_version", "modulo", "pantalla", "pestana", "numero_version", "es_publicada", "es_borrador", "snapshot", "diff", "motivo", "impacto_resumen", "id_usuario_creacion", "fecha_creacion") VALUES (34, 'gestion_de_cambios', '1.3.3.1', 'plantillas', 0, false, true, '{"secciones":[{"id":"sec_a","color":"#2563eb","orden":1,"campos":[{"tipo":"texto","ancho":"completo","ayuda":"Mínimo 10 y máximo 150 caracteres. El sistema sugiere RFCs similares.","codigo":"titulo","reglas":[],"visible":true,"etiqueta":"Título del cambio","bloqueado":true,"obligatorio":"si","placeholder":"Resumen claro y conciso de la intervención técnica..."},{"tipo":"selector_modelo","ancho":"1/2","ayuda":"Exigido para cambios estándar. Prellena planes y fija el riesgo.","codigo":"modelo_id","reglas":[{"valor":"ESTANDAR","accion":"mostrar","operador":"igual","si_campo":"tipo_cambio"}],"visible":true,"etiqueta":"Modelo de cambio estándar","bloqueado":false,"obligatorio":"condicional","tipo_cambio_aplicable":"ESTANDAR"},{"tipo":"cascada_categoria","ancho":"1/2","ayuda":"Clasificación tecnológica del objeto de cambio.","codigo":"categoria_id","reglas":[],"visible":true,"etiqueta":"Categoría del cambio","bloqueado":false,"obligatorio":"si"},{"tipo":"lista_origen","ancho":"1/2","ayuda":"Problema, Incidente, Solicitud, Mejora, Proyecto, etc.","codigo":"origen","reglas":[],"visible":true,"etiqueta":"Origen del cambio","bloqueado":false,"obligatorio":"si"},{"tipo":"buscador_ticket","ancho":"completo","ayuda":"Obligatorio si el origen es Problema o Incidente.","codigo":"ticket_origen","reglas":[{"valor":"problema,incidente,solicitud_servicio","accion":"hacer_obligatorio","operador":"es_uno_de","si_campo":"origen"}],"visible":true,"etiqueta":"Ticket de origen vinculado","bloqueado":false,"obligatorio":"condicional"}],"codigo":"identificacion","titulo":"Identificación del Cambio"},{"id":"sec_b","color":"#0891b2","orden":2,"campos":[{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Mínimo 30 caracteres. Sustento formal del cambio.","codigo":"motivo","reglas":[],"visible":true,"etiqueta":"Motivo / Justificación de negocio","bloqueado":true,"obligatorio":"si","placeholder":"Por qué es necesario y qué objetivo u oportunidad atiende..."},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Mínimo 50 caracteres.","codigo":"descripcion","reglas":[],"visible":true,"etiqueta":"Descripción técnica detallada","bloqueado":true,"obligatorio":"si","placeholder":"Qué se modifica, en qué sistema o componente, y resultado esperado..."},{"tipo":"texto","ancho":"1/2","codigo":"beneficio","reglas":[],"visible":true,"etiqueta":"Beneficio esperado","bloqueado":false,"obligatorio":"no","placeholder":"Ganancia tangible de rendimiento, estabilidad o cumplimiento..."},{"tipo":"area_enriquecida","ancho":"1/2","ayuda":"Impacto técnico o financiero si el cambio es denegado.","codigo":"consecuencia_no_hacer","reglas":[],"visible":true,"etiqueta":"Consecuencia de NO realizar el cambio (Riesgo por Inacción)","bloqueado":false,"obligatorio":"si","placeholder":"Riesgos de inacción o postergación ante rechazo del comité..."}],"codigo":"justificacion","titulo":"Justificación y Descripción Técnica"},{"id":"sec_c","color":"#16a34a","orden":3,"campos":[{"tipo":"selector_servicios","ancho":"1/2","ayuda":"Servicios del catálogo impactados por la intervención.","codigo":"servicios","reglas":[],"visible":true,"etiqueta":"Servicio(s) primario(s) afectado(s)","bloqueado":true,"obligatorio":"si"},{"tipo":"selector_cmdb_multiple","ancho":"1/2","ayuda":"Elementos de configuración sujetos a modificación técnica (permite asociar múltiples CIs).","codigo":"ci_afectados","reglas":[],"visible":true,"etiqueta":"Activos / CIs afectados (CMDB)","bloqueado":true,"obligatorio":"si"},{"tipo":"lista_entorno","ancho":"1/3","ayuda":"Producción, Preproducción, Pruebas o Desarrollo.","codigo":"entorno","reglas":[],"visible":true,"etiqueta":"Entorno operativo","bloqueado":false,"obligatorio":"si"},{"tipo":"selector_departamentos","ancho":"1/3","ayuda":"Unidades organizacionales usuarias del servicio.","codigo":"areas_afectadas","reglas":[],"visible":true,"etiqueta":"Áreas / Departamentos afectados","bloqueado":false,"obligatorio":"no"},{"tipo":"numero","ancho":"1/3","ayuda":"Alimenta el cálculo automático de riesgo.","codigo":"usuarios_afectados","reglas":[],"visible":true,"etiqueta":"Usuarios afectados estimados","bloqueado":false,"obligatorio":"no","placeholder":"0"}],"codigo":"alcance","titulo":"Alcance y Elementos CI (CMDB)"},{"id":"sec_d","color":"#d97706","orden":4,"campos":[{"tipo":"selector_impacto","ancho":"1/3","ayuda":"Nivel de impacto técnico y operativo sobre el servicio.","codigo":"impacto","reglas":[],"visible":true,"etiqueta":"Impacto del cambio en el negocio","bloqueado":true,"obligatorio":"si"},{"tipo":"selector_riesgo","ancho":"1/3","ayuda":"Complejidad técnica de la intervención.","codigo":"riesgo_tecnico","reglas":[],"visible":true,"etiqueta":"Riesgo técnico estimado","bloqueado":true,"obligatorio":"si"},{"tipo":"prioridad_insignia","ancho":"1/3","ayuda":"Resuelta automáticamente según la Matriz de Cambios.","codigo":"prioridad","reglas":[],"visible":true,"etiqueta":"Prioridad calculada (Impacto × Riesgo)","bloqueado":true,"obligatorio":"no","solo_lectura":true},{"tipo":"cuestionario_riesgo","ancho":"completo","ayuda":"Evaluación multidimensional de riesgo conforme a ITIL 4 y COBIT.","codigo":"riesgo_respuestas","reglas":[],"visible":true,"etiqueta":"Cuestionario de riesgo ponderado","bloqueado":false,"obligatorio":"segun_tipo"}],"codigo":"evaluacion","titulo":"Evaluación de Prioridad y Riesgo"},{"id":"sec_e","color":"#7c3aed","orden":5,"campos":[{"tipo":"fechahora","ancho":"1/2","ayuda":"Fecha y hora de inicio de intervención. Sujeto a anticipación mínima.","codigo":"fecha_inicio","reglas":[],"visible":true,"etiqueta":"Inicio propuesto de ventana","bloqueado":true,"obligatorio":"si"},{"tipo":"fechahora","ancho":"1/2","ayuda":"Fecha y hora de término pactada.","codigo":"fecha_fin","reglas":[],"visible":true,"etiqueta":"Fin propuesto de ventana","bloqueado":true,"obligatorio":"si"},{"tipo":"booleano","ancho":"1/2","ayuda":"Indica indisponibilidad para los usuarios finales.","codigo":"requiere_interrupcion","reglas":[],"visible":true,"etiqueta":"¿Requiere interrupción de servicio?","bloqueado":false,"obligatorio":"si"},{"tipo":"texto","ancho":"1/2","ayuda":"Obligatorio si requiere interrupción.","codigo":"duracion_interrupcion","reglas":[{"valor":true,"accion":"hacer_obligatorio","operador":"igual","si_campo":"requiere_interrupcion"}],"visible":true,"etiqueta":"Duración estimada de interrupción","bloqueado":false,"obligatorio":"condicional","placeholder":"Ej. 30m, 2h"},{"tipo":"selector_ventana","ancho":"completo","ayuda":"Franja de mantenimiento programada institucional.","codigo":"ventana_id","reglas":[],"visible":true,"etiqueta":"Ventana de mantenimiento aplicable","bloqueado":false,"obligatorio":"no"}],"codigo":"programacion","titulo":"Programación y Ventana de Mantenimiento"},{"id":"sec_f","color":"#059669","orden":6,"campos":[{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Obligatorio para Normal y Emergencia.","codigo":"plan_implementacion","reglas":[],"visible":true,"etiqueta":"Plan detallado de implementación paso a paso","bloqueado":true,"obligatorio":"si","placeholder":"Paso a paso técnico, comandos, validaciones y responsables..."},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Obligatorio por gobernanza ITIL/ISO 20000.","codigo":"plan_rollback","reglas":[],"visible":true,"etiqueta":"Plan de rollback (Marcha atrás / Reversión)","bloqueado":true,"obligatorio":"si","placeholder":"Procedimiento de retorno seguro ante fallas..."},{"tipo":"texto","ancho":"completo","ayuda":"Momento exacto en que se descarta rollback y se fuerza hacia adelante.","codigo":"punto_no_retorno","reglas":[],"visible":true,"etiqueta":"Punto de no retorno (Forward-Fix Boundary)","bloqueado":false,"obligatorio":"si","placeholder":"Hito temporal o técnico tras el cual el rollback ya no es viable..."},{"tipo":"area_enriquecida","ancho":"completo","codigo":"plan_pruebas","reglas":[],"visible":true,"etiqueta":"Plan de pruebas / Validación post-cambio","bloqueado":false,"obligatorio":"si","placeholder":"Pruebas unitarias, funcionales o de integración planificadas..."},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Métricas cuantitativas y condiciones verificables para declarar el cambio Exitoso.","codigo":"criterios_exito","reglas":[],"visible":true,"etiqueta":"Criterios de éxito y aceptación","bloqueado":false,"obligatorio":"si"},{"tipo":"selector_grupo","ancho":"1/2","ayuda":"Equipo técnico que ejecutará los trabajos.","codigo":"grupo_implementador_id","reglas":[],"visible":true,"etiqueta":"Grupo implementador asignado","bloqueado":true,"obligatorio":"si"},{"tipo":"selector_tecnico","ancho":"1/2","ayuda":"No puede ser el aprobador de esta RFC (segregación de funciones).","codigo":"implementador_id","reglas":[],"visible":true,"etiqueta":"Especialista técnico responsable","bloqueado":false,"obligatorio":"segun_tipo"}],"codigo":"planes","titulo":"Planes Técnicos Mandatorios y Gobernanza CAB"},{"id":"sec_g","color":"#dc2626","orden":7,"campos":[{"tipo":"buscador_ticket","ancho":"1/2","ayuda":"Incidente P1 que fuerza la intervención de emergencia (Mandatorio).","codigo":"ticket_emergencia","reglas":[],"visible":true,"etiqueta":"Incidente Mayor crítico motivador (#INC)","bloqueado":true,"obligatorio":"si"},{"tipo":"lista_medio_autorizacion","ancho":"1/2","ayuda":"Llamada grabada en sala de crisis, canal Teams/Slack o aprobación 1-clic.","codigo":"medio_autorizacion_emergencia","reglas":[],"visible":true,"etiqueta":"Medio de autorización inmediata (ECAB)","bloqueado":false,"obligatorio":"si"},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Mínimo 30 caracteres.","codigo":"justificacion_emergencia","reglas":[],"visible":true,"etiqueta":"Justificación de emergencia y causa de urgencia","bloqueado":true,"obligatorio":"si","placeholder":"Motivo crítico por el cual no puede esperar el ciclo CAB normal..."},{"tipo":"texto","ancho":"completo","codigo":"consecuencia_emergencia","reglas":[],"visible":true,"etiqueta":"Consecuencia de no actuar de inmediato","bloqueado":false,"obligatorio":"si","placeholder":"Impacto catastrófico evitado..."}],"codigo":"emergencia","titulo":"Justificación de Crisis y ECAB (Emergencia)","es_condicional_emergencia":true},{"id":"sec_pir","color":"#9333ea","orden":8,"campos":[{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Explicación técnica del origen del fallo.","codigo":"causa_raiz_tecnica","reglas":[],"visible":true,"etiqueta":"Causa raíz técnica de la falla de origen","bloqueado":false,"obligatorio":"si","placeholder":"Análisis 5 Porqués o Ishikawa de la falla..."},{"tipo":"numero","ancho":"1/2","ayuda":"Minutos de caída real del servicio.","codigo":"tiempo_downtime_real","reglas":[],"visible":true,"etiqueta":"Tiempo real de indisponibilidad del servicio (minutos)","bloqueado":false,"obligatorio":"si","placeholder":"0"},{"tipo":"booleano","ancho":"1/2","ayuda":"Indica si generó fallas adicionales.","codigo":"incidente_colateral","reglas":[],"visible":true,"etiqueta":"¿Provocó incidentes secundarios no deseados?","bloqueado":false,"obligatorio":"si"},{"tipo":"buscador_ticket","ancho":"completo","ayuda":"Ticket de gestión de problemas para erradicar causa raíz.","codigo":"ticket_problema_preventivo","reglas":[],"visible":true,"etiqueta":"Ticket de Problema preventivo asociado (#PRB)","bloqueado":false,"obligatorio":"no"},{"tipo":"area_enriquecida","ancho":"completo","ayuda":"Compromiso de mejora continua.","codigo":"lecciones_aprendidas","reglas":[],"visible":true,"etiqueta":"Lecciones aprendidas y mejoras de prevención","bloqueado":false,"obligatorio":"si","placeholder":"Qué controles o pruebas faltaron antes de producción..."}],"codigo":"pir","titulo":"Ficha Post-Mortem Mandatoria (PIR)"},{"id":"sec_h","color":"#64748b","orden":9,"campos":[{"tipo":"adjuntos","ancho":"completo","ayuda":"Diagramas, scripts, manuales de proveedor (máx. 25 MB por archivo).","codigo":"adjuntos","reglas":[],"visible":true,"etiqueta":"Archivos adjuntos, evidencias y scripts","bloqueado":false,"obligatorio":"no"}],"codigo":"evidencias","titulo":"Evidencias y Documentación Técnica"}],"campos_bloqueados":["titulo","motivo","descripcion","servicios","ci_afectados","impacto","urgencia","fecha_inicio","fecha_fin","plan_implementacion","plan_rollback","grupo_implementador_id"],"formulario_activo":"solicitud"}'::jsonb, '{"tipo":"borrador"}'::jsonb, 'Guardado de borrador en pestaña plantillas', 'Borrador activo sin publicar', 1, '2026-11-15T17:27:39.177Z') ON CONFLICT DO NOTHING;
