INSERT INTO "configuracion_sistema" ("clave", "categoria", "descripcion", "valor", "usuario_modificacion", "fecha_modificacion") VALUES ('plantillas_correo_html', 'NOTIFICACIONES', 'Plantillas HTML y diseño corporativo de correos del sistema', '{"logo_url":"https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=160&auto=format&fit=crop&q=80","plantillas":{"cambio_cab":{"asunto":"Convocatoria CAB para Solicitud de Cambio: [{{codigo_cambio}}]","cuerpo":"Estimado Miembro del CAB,\n\nSe ha programado una solicitud de cambio que requiere evaluación de contingencias y análisis de impacto en la infraestructura.","encabezado":"Revisión y Dictamen Colegiado del Comité CAB","destinatarios":{"cab":true,"tecnico":true,"supervisor":true,"solicitante":false}},"ticket_creado":{"asunto":"Ticket Registrado: [{{codigo_ticket}}] {{titulo}}","cuerpo":"Estimado/a {{solicitante_nombre}},\n\nHemos recibido satisfactoriamente su requerimiento en la Mesa de Servicio. Un especialista asignado procederá a su atención dentro del plazo comprometido por el acuerdo de nivel de servicio (SLA).\n\nPuede consultar el avance y la línea de tiempo en el portal.","encabezado":"Su requerimiento ha sido registrado formalmente","destinatarios":{"tecnico":false,"supervisor":true,"solicitante":true}},"ticket_resuelto":{"asunto":"Ticket Resuelto: [{{codigo_ticket}}] {{titulo}}","cuerpo":"Estimado/a {{solicitante_nombre}},\n\nLe informamos que el caso {{codigo_ticket}} ha sido resuelto por el equipo técnico resolutor.\n\nPor favor ingrese al sistema para calificar el servicio y confirmar el cierre definitivo del caso.","encabezado":"El servicio ha sido restablecido","destinatarios":{"tecnico":true,"supervisor":true,"solicitante":true}}},"color_primario":"#2563eb","nombre_empresa":"Sistema Institucional de Gestión de Servicios TI"}'::jsonb, NULL, '2026-09-30T17:13:19.094Z') ON CONFLICT DO NOTHING;
INSERT INTO "configuracion_sistema" ("clave", "categoria", "descripcion", "valor", "usuario_modificacion", "fecha_modificacion") VALUES ('canales_comunicacion', 'NOTIFICACIONES', 'Configuración de canales externos para mensajería y alertas', '{"sms":{"activo":false,"proveedor":"Twilio Gateway","remitente":"MESA_TI","account_sid":""},"slack":{"canal":"#soporte-critico-ti","activo":true,"webhook_url":"https://hooks.slack.com/services/T00/B00/XXXXX"},"teams":{"canal":"Alertas Infraestructura TI","activo":false,"webhook_url":"https://outlook.office.com/webhook/XXXXX"},"whatsapp":{"activo":false,"proveedor":"Meta Cloud API","webhook_url":"","telefono_remitente":"+51 900 000 000"}}'::jsonb, NULL, '2026-09-30T17:13:19.213Z') ON CONFLICT DO NOTHING;
