INSERT INTO "configuracion_sistema" ("clave", "categoria", "descripcion", "valor", "usuario_modificacion", "fecha_modificacion") VALUES ('formularios_solicitante_config', 'GENERAL', 'Configuración de visibilidad, obligatoriedad y prioridades de usuario para formularios y tickets de solicitantes', '{"incidente":[{"id":"en_nombre_de_otro","tipo":"casilla","etiqueta":"Registrar en nombre de otro usuario (Afectado)","habilitado":true,"descripcion":"Permite al solicitante registrar el incidente a nombre de un tercero o colaborador a su cargo.","obligatorio":false,"prioridad_minima":4},{"id":"sede_atencion","tipo":"lista","etiqueta":"Sede o Ubicación Física de la Falla","opciones":"Sede Central, Oficina Miraflores, Planta Industrial, Teletrabajo / Remoto","habilitado":true,"descripcion":"Oficina, filial o piso exacto donde ocurre la incidencia para despacho presencial.","obligatorio":false,"prioridad_minima":5},{"id":"anexo_contacto_urgente","tipo":"texto","etiqueta":"Teléfono Móvil o Anexo de Contacto Urgente","habilitado":true,"descripcion":"Número telefónico directo del solicitante para coordinar el diagnóstico técnico inmediato.","obligatorio":false,"prioridad_minima":5},{"id":"centro_costos","tipo":"texto","etiqueta":"Centro de Costos / Proyecto Afectado","habilitado":true,"descripcion":"Identificador contable para registro y análisis de costos de mantenimiento y repuestos.","obligatorio":false,"prioridad_minima":4}],"solicitud":[{"id":"en_nombre_de_otro","tipo":"casilla","etiqueta":"Registrar en nombre de otro usuario (Afectado / Beneficiario)","habilitado":true,"descripcion":"Permite registrar la solicitud de servicio para otro colaborador del departamento.","obligatorio":false,"prioridad_minima":3},{"id":"sede_entrega","tipo":"lista","etiqueta":"Sede o Ubicación de Entrega del Recurso","opciones":"Sede Central, Oficina Miraflores, Planta Industrial, Teletrabajo / Remoto","habilitado":true,"descripcion":"Oficina física a la que debe enviarse el equipo o habilitarse