INSERT INTO "error_conocido" ("id_error_conocido", "id_problema", "codigo_kedb", "titulo", "sintomas", "workaround", "solucion_definitiva", "fecha_publicacion", "estado_registro") VALUES (2, 2, 'KEDB-002', 'Saturacion de memoria compartida en reportes ERP', 'El navegador responde con error HTTP 504 Gateway Timeout al generar reportes de mas de 1000 paginas.', 'Descargar el reporte en formato CSV plano en lugar de PDF previsualizado.', 'Crear indices cubrientes en PostgreSQL sobre fecha_movimiento y id_cuenta_contable.', '2026-09-29T00:59:20.236Z', true) ON CONFLICT DO NOTHING;
