INSERT INTO "perfiles" ("id_perfil", "nombre", "descripcion", "estado_registro") VALUES (3, 'Solicitante', 'Crea tickets y hace seguimiento a los suyos', true) ON CONFLICT DO NOTHING;
INSERT INTO "perfiles" ("id_perfil", "nombre", "descripcion", "estado_registro") VALUES (4, 'Supervisor', 'Supervisa la operacion de tickets (ver todos, reasignar, reportes) sin configurar el sistema', true) ON CONFLICT DO NOTHING;
INSERT INTO "perfiles" ("id_perfil", "nombre", "descripcion", "estado_registro") VALUES (5, 'Gestor de Area', 'Aprueba requerimientos y supervisa el servicio recibido por su departamento', true) ON CONFLICT DO NOTHING;
INSERT INTO "perfiles" ("id_perfil", "nombre", "descripcion", "estado_registro") VALUES (6, 'Auditor', 'Consulta integral de auditoría, logs de seguridad y reportes de cumplimiento sin modificar datos', true) ON CONFLICT DO NOTHING;
INSERT INTO "perfiles" ("id_perfil", "nombre", "descripcion", "estado_registro") VALUES (7, 'Aprobador', 'Autoridad de Cambio (CAB): evalúa impacto y autoriza solicitudes de cambio (RFC)', true) ON CONFLICT DO NOTHING;
