INSERT INTO "problema" ("id_problema", "codigo_problema", "titulo", "descripcion", "id_impacto", "id_urgencia", "id_prioridad", "id_estado", "causa_raiz", "metodo_analisis", "workaround", "es_error_conocido", "id_ci_afectado", "id_usuario_asignado", "id_departamento", "solucion_definitiva", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion", "estado_registro") VALUES (1, 'PRB-2026-0001', 'Microcortes aleatorios y desconexion en VPN corporativa SSL', 'Multiples colaboradores de diversas sedes reportan desconexiones de la VPN cada 45 minutos durante llamadas y transferencias.', 3, 3, 1, 3, 'Saturacion de conexiones simultaneas por asignacion insuficiente de pool de memoria en el Gateway perimetral.', '5_WHYS', 'Reiniciar el servicio openvpn-daemon en el nodo secundario y derivar usuarios al Gateway B.', true, 3, 1, 3, NULL, 1, '2026-09-29T00:59:20.236Z', NULL, NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO "problema" ("id_problema", "codigo_problema", "titulo", "descripcion", "id_impacto", "id_urgencia", "id_prioridad", "id_estado", "causa_raiz", "metodo_analisis", "workaround", "es_error_conocido", "id_ci_afectado", "id_usuario_asignado", "id_departamento", "solucion_definitiva", "usuario_creacion", "fecha_creacion", "usuario_modificacion", "fecha_modificacion", "estado_registro") VALUES (2, 'PRB-2026-0002', 'Lentitud y cuelgues recurrentes en reportes financieros del ERP', 'El módulo de consolidación contable se congela al emitir balances mensuales afectando a Gerencia de Finanzas.', 2, 2, 2, 4, 'Consultas de indices secuenciales sin cache en tablas de auditoria con mas de 5 millones de registros.', 'ISHIKAWA', 'Ejecutar VACUUM ANALYZE manual y restringir el rango de fechas de consulta a 6 meses.', true, 2, 1, 4, NULL, 1, '2026-09-29T00:59:20.236Z', NULL, NULL, true) ON CONFLICT DO NOTHING;
