INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (1, 'metodo_5_porques', '5 porqués', 'Técnica iterativa interrogativa para explorar relaciones de causa-efecto', '#6366f1', 1, true, true, '1. ¿Por qué ocurrió la falla inicial?\n2. ¿Por qué se produjo esa condición?\n3. ¿Por qué no fue detectada por los controles?\n4. ¿Por qué existía esa vulnerabilidad o debilidad?\n5. ¿Por qué no se corrigió oportunamente? (Causa Raíz)') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (2, 'metodo_ishikawa', 'Diagrama de Ishikawa (Espina de Pescado)', 'Análisis causal clasificando por 6M: Método, Mano de obra, Material, Máquina, Medición, Medio ambiente', '#4f46e5', 2, true, true, 'Mano de obra:\nMáquina / Hardware:\nMétodo / Procedimiento:\nMaterial / Software:\nMedición:\nMedio ambiente:') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (3, 'metodo_arbol_fallas', 'Árbol de fallas (FTA)', 'Análisis deductivo descendente con puertas lógicas booleanas Y/O', '#4338ca', 3, true, true, 'Evento no deseado superior:\n- Hipótesis A (Condición 1 Y Condición 2)\n- Hipótesis B (Falla de redundancia)') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (4, 'metodo_kepner_tregoe', 'Kepner-Tregoe', 'Metodología analítica estructurada para identificar causas mediante Qué es / Qué no es', '#3730a3', 4, true, true, 'Identidad (Qué es / Qué no es):\nUbicación (Dónde es / Dónde no es):\nTiempo (Cuándo es / Cuándo no es):\nMagnitud (Cuánto abarca / Cuánto no abarca):') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (5, 'metodo_cronologico', 'Análisis cronológico', 'Reconstrucción de la línea de tiempo minuto a minuto de eventos y logs', '#2563eb', 5, true, true, 'Línea de tiempo consolidada:\n- [HH:MM] Evento preliminar registrado en syslog\n- [HH:MM] Anomalía reportada por usuarios\n- [HH:MM] Interrupción del servicio') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (6, 'metodo_cambios_recientes', 'Análisis de cambios recientes', 'Revisión y contraste con las RFCs y despliegues ejecutados en las últimas 72 horas', '#0891b2', 6, true, true, 'Cambios evaluados:\n- RFC-XXXXX: Modificación en base de datos\n- Despliegue de versión en servidor web') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (7, 'metodo_pareto', 'Análisis de Pareto (80/20)', 'Identificación de las pocas causas vitales que originan la mayoría de los incidentes', '#059669', 7, true, true, 'Frecuencia de incidentes por categoría y concentración del 80% del impacto') ON CONFLICT DO NOTHING;
INSERT INTO "problema_metodo_analisis" ("id_metodo", "codigo", "nombre", "descripcion", "color", "orden", "activo", "es_sistema", "plantilla_ayuda") VALUES (8, 'metodo_otro', 'Otro método documentado', 'Metodología técnica personalizada con sustento documental adjunto', '#64748b', 8, true, true, 'Describa el método de análisis aplicado y justificación:') ON CONFLICT DO NOTHING;
