INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (35, 'SRV-SOL-CAP-002', 2, 22, 'Soporte guiado en el puesto de trabajo (acompañamiento presencial o remoto)', 'Incluye: sesión individual de hasta 60 minutos para resolver dudas de uso de herramientas informáticas autorizadas. No incluye: resolución de fallas técnicas (se reporta como incidente) ni capacitación grupal.', 'Acompañamiento realizado y confirmado por el usuario, con las dudas resueltas y los puntos tratados registrados en el ticket.', false, 48, 8, '0.00', 'capacitacion', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (36, 'SRV-SOL-BKP-002', 2, 9, 'Respaldo extraordinario de información de equipo o carpeta', 'Incluye: copia de seguridad puntual de carpetas o del perfil de un equipo antes de un formateo, cambio de equipo o proceso crítico, con verificación de integridad. No incluye: respaldos periódicos programados ni respaldo de información personal no laboral.', 'Respaldo completado y verificado por muestreo, con ubicación y fecha de retención informadas al solicitante.', false, 48, 8, '0.00', 'backup', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (37, 'SRV-INC-HW-001', 1, 1, 'Laptop o computadora de escritorio no enciende o se reinicia sola', 'Reporte de equipos que no encienden, no cargan, no inician el sistema o se apagan o reinician solos. Indique código del equipo, qué ocurrió justo antes de la falla y si hay mensajes o luces en pantalla. Incluye diagnóstico y restablecimiento o reemplazo temporal. No incluye: compra de equipos nuevos.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 8, 2, '0.00', 'hardware', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (38, 'SRV-INC-HW-002', 1, 1, 'Monitor, teclado, mouse o periférico de escritorio no funciona', 'Reporte de fallas en monitores, teclados, mouse, cámaras web, diademas u otros periféricos conectados al equipo. Indique el modelo y si el problema ocurre en otro puerto o equipo. Incluye diagnóstico, ajuste, reemplazo del periférico si existe stock. No incluye: reparación de daños por mal uso fuera de garantía.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'hardware', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (39, 'SRV-INC-SW-001', 1, 3, 'Aplicación de negocio (ERP) lenta, con errores o sin respuesta', 'Reporte de lentitud severa, mensajes de error, cuelgues o indisponibilidad del sistema ERP u otra aplicación de negocio. Indique módulo, hora y duración, mensaje o código de error y cuántos usuarios están afectados. Incluye diagnóstico, restablecimiento y escalamiento al proveedor. No incluye: nuevos requerimientos funcionales.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 8, 2, '0.00', 'software', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (40, 'SRV-INC-SW-002', 1, 3, 'Software de escritorio se cierra inesperadamente o no abre', 'Reporte de programas de ofimática, navegadores o software instalado que se cierran solos, no abren o muestran errores al iniciar. Indique nombre y versión del programa y el mensaje de error. Incluye reparación, reinstalación o ajuste de configuración. No incluye: instalación de software nuevo (se solicita en el catálogo de solicitudes).', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'software', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (41, 'SRV-INC-INF-001', 1, 11, 'Servidor físico o virtual caído o sin respuesta', 'Reporte de servidores que no responden, no inician o están fuera de servicio, con afectación de aplicaciones o usuarios. Indique nombre del servidor, servicios afectados y hora de inicio. Incluye diagnóstico, restablecimiento y escalamiento a proveedor. No incluye: ampliaciones de capacidad (se solicitan como servicio).', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 4, 1, '0.00', 'servidor', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (42, 'SRV-INC-INF-002', 1, 11, 'Alarma de recursos críticos en servidor (CPU, memoria o disco al límite)', 'Reporte de alertas o degradación por uso excesivo de CPU, memoria o espacio en disco en servidores. Indique el servidor, el recurso afectado y el porcentaje de uso. Incluye liberación de recursos, ajustes inmediatos y recomendación de ampliación. No incluye: la ampliación definitiva, que se tramita como solicitud.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 8, 2, '0.00', 'servidor', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (43, 'SRV-INC-DB-001', 1, 12, 'Base de datos no disponible, con bloqueos o consultas muy lentas', 'Reporte de indisponibilidad, bloqueos, errores de conexión o lentitud severa en bases de datos. Indique el sistema, la base de datos, el mensaje de error y la hora de inicio. Incluye diagnóstico, restablecimiento y escalamiento al administrador de la base de datos. No incluye: consultas o reportes nuevos.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 4, 1, '0.00', 'base_datos', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (44, 'SRV-INC-DB-002', 1, 12, 'Cuota de disco o almacenamiento compartido agotada', 'Reporte de falta de espacio en carpetas compartidas, discos de servidor o almacenamiento SAN que impide guardar o procesar información. Indique la ruta o el volumen y el mensaje recibido. Incluye liberación de espacio y ajuste temporal de cuota. No incluye: ampliaciones permanentes (se solicitan como servicio).', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 8, 2, '0.00', 'base_datos', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (45, 'SRV-INC-TEL-001', 1, 13, 'Caída de la central telefónica IP o sin tono de llamada', 'Reporte de pérdida total o parcial de telefonía: sin tono, llamadas que se cortan o teléfonos desregistrados. Indique extensiones y áreas afectadas. Incluye diagnóstico de la central, la red de voz y los teléfonos, y escalamiento al proveedor de telefonía. No incluye: altas de nuevas extensiones.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 4, 1, '0.00', 'telefono', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (46, 'SRV-INC-TEL-002', 1, 13, 'Fallas de audio o conexión en plataforma de videoconferencia', 'Reporte de cortes de audio, video, imposibilidad de ingresar a reuniones o fallas de diademas y cámaras en la plataforma de videoconferencia. Indique la plataforma, la hora y si ocurre en un solo equipo o en varios. Incluye diagnóstico y corrección de configuración. No incluye: organización técnica de eventos.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'telefono', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (47, 'SRV-INC-PRN-001', 1, 14, 'Impresora departamental atascada o sin imprimir', 'Reporte de atascos de papel, cola de impresión detenida, impresiones con manchas o impresora fuera de línea. Indique el modelo o la ubicación de la impresora y el mensaje del panel. Incluye diagnóstico, limpieza, reinicio del servicio de impresión y reposición de insumos si hay stock. No incluye: compra de impresoras nuevas.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'impresora', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (48, 'SRV-INC-PRN-002', 1, 14, 'Escáner o multifuncional no digitaliza o no envía a correo', 'Reporte de escáneres o multifuncionales que no digitalizan, no envían a correo o a carpeta de red. Indique modelo, ubicación y mensaje de error. Incluye revisión de configuración, credenciales y conectividad. No incluye: instalación de software de digitalización avanzado.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 72, 8, '0.00', 'impresora', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (49, 'SRV-INC-MAIL-001', 1, 15, 'No se envían o reciben correos corporativos', 'Reporte de imposibilidad de enviar o recibir correo, rebotes o retrasos importantes. Indique la cuenta afectada, el mensaje de error y si ocurre con destinatarios internos, externos o ambos. Incluye diagnóstico del buzón, del cliente y del servicio y escalamiento al proveedor. No incluye: recuperación de correos eliminados hace más de 30 días.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 8, 2, '0.00', 'correo', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (50, 'SRV-INC-MAIL-002', 1, 15, 'Calendario o buzón no sincroniza en celular o en el cliente de correo', 'Reporte de calendario, contactos o correos que no sincronizan en el celular, la aplicación de escritorio o el navegador. Indique el dispositivo, el cliente y desde cuándo ocurre. Incluye reconfiguración del perfil y de la cuenta. No incluye: configuración de cuentas personales.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'correo', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (51, 'SRV-INC-CLD-001', 1, 16, 'Servicio alojado en la nube inaccesible o con degradación', 'Reporte de aplicaciones, sitios o servicios alojados en la nube que no responden o están degradados. Indique el servicio, la URL, el mensaje de error y los usuarios afectados. Incluye diagnóstico, restablecimiento y escalamiento al proveedor cloud. No incluye: rediseño de arquitectura.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 4, 1, '0.00', 'cloud', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (52, 'SRV-INC-CLD-002', 1, 16, 'Falla en pipeline de integración y despliegue continuo (CI/CD)', 'Reporte de pipelines que fallan, se quedan detenidos o no despliegan. Indique el repositorio, el pipeline, el paso donde falla y el registro del error. Incluye diagnóstico, corrección de configuración o credenciales y reejecución. No incluye: desarrollo de nuevos pipelines.', 'Servicio restablecido y confirmado por el usuario, con causa y solución aplicada registradas en el ticket.', false, 24, 4, '0.00', 'cloud', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "servicio_catalogo" ("id_servicio", "codigo_servicio", "id_tipo_ticket", "id_categoria", "nombre", "descripcion_comercial", "entregable", "requiere_aprobacion", "sla_horas_resolucion", "sla_horas_respuesta", "costo_referencial", "icono", "estado_registro", "motivo_inactivacion", "fecha_inactivacion", "usuario_inactivacion", "esquema_formulario", "id_departamento_resolutor", "reglas_escalamiento", "es_critico", "responsable_servicio_id") VALUES (53, 'SRV-SOL-HW-008', 2, 5, 'Revision de impresoras', 'Arreglar impresora', 'Entrega del equipo a larea', false, 24, 4, '0.00', 'servicio', true, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, false, NULL) ON CONFLICT DO NOTHING;
